SOURCE = r'''
def context_main(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) >= 64:
        if read_word(s, 0) == @MATH_MAGIC@:
            return ctx_math_main(s, o, w)
    if length(s) == 64:
        if read_word(s, 0) == @EMIT_MAGIC@:
            return emit_exception_delivery(s, o, w)
